import{_ as a,o as r,c as e,a3 as n}from"./chunks/framework.DMtjdCb-.js";const o="/help/assets/hidden-works.SJUKkt54.png",s="/help/assets/library-settings.WC-UF7UC.png",d="/help/assets/history.DW7vX8Ff.png",b=JSON.parse('{"title":"8. 日常管理","description":"","frontmatter":{},"headers":[],"relativePath":"zh-Hans/manage.md","filePath":"zh-Hans/manage.md"}'),i={name:"zh-Hans/manage.md"};function l(h,t,p,c,g,_){return r(),e("div",null,[...t[0]||(t[0]=[n('<h1 id="_8-日常管理" tabindex="-1">8. 日常管理 <a class="header-anchor" href="#_8-日常管理" aria-label="Permalink to &quot;8. 日常管理&quot;">​</a></h1><h2 id="查找、筛选与隐藏" tabindex="-1">查找、筛选与隐藏 <a class="header-anchor" href="#查找、筛选与隐藏" aria-label="Permalink to &quot;查找、筛选与隐藏&quot;">​</a></h2><p>首页可切换卡片和表格，按年代、类型、资源来源和收藏状态筛选。<strong>重置全部</strong> 返回默认筛选；直接输入标题可查找被默认筛选或隐藏的作品。</p><p>在雷达或详情中将作品设为 <strong>已隐藏</strong>，它会从默认作品列表和雷达中移除。原有订阅、下载与观看记录保持不变。</p><p>要还原时，打开 <strong>新作雷达 → 已隐藏作品</strong>，找到作品并点击还原。</p><p><img src="'+o+'" alt="隐藏作品：在集中列表中搜索并还原" loading="lazy"></p><h2 id="暂停、取消与删除订阅" tabindex="-1">暂停、取消与删除订阅 <a class="header-anchor" href="#暂停、取消与删除订阅" aria-label="Permalink to &quot;暂停、取消与删除订阅&quot;">​</a></h2><p>在雷达的订阅状态菜单或作品详情中选择需要的操作：</p><table tabindex="0"><thead><tr><th>操作</th><th>后续更新</th><th>已有文件</th></tr></thead><tbody><tr><td>暂停订阅</td><td>暂停自动获取，可恢复</td><td>保留</td></tr><tr><td>取消订阅（保留文件）</td><td>停止订阅</td><td>保留</td></tr><tr><td>删除订阅（含文件）</td><td>删除订阅</td><td>按确认页面删除对应文件</td></tr><tr><td>隐藏作品</td><td>原订阅继续运行</td><td>保留</td></tr></tbody></table><p>涉及删除文件时，先核对确认窗口中的作品和操作范围，再确认。</p><h2 id="建立订阅目录" tabindex="-1">建立订阅目录 <a class="header-anchor" href="#建立订阅目录" aria-label="Permalink to &quot;建立订阅目录&quot;">​</a></h2><p>本地收藏库已连接且可写时，雷达中的 <strong>建立目录</strong> 可为已订阅作品建立占位目录。已有目录继续使用，之后可在历史记录中查看结果。</p><h2 id="设置收藏库休眠时段" tabindex="-1">设置收藏库休眠时段 <a class="header-anchor" href="#设置收藏库休眠时段" aria-label="Permalink to &quot;设置收藏库休眠时段&quot;">​</a></h2><ol><li>打开 <strong>设置 → 连接 → 本地收藏库</strong>。</li><li>勾选 <strong>启用每日休眠时段</strong>，设置开始与结束时间。</li><li>核对页面显示的运行设备时间，保存设置。</li></ol><p><img src="'+s+'" alt="休眠时段：核对运行设备时间后设置" loading="lazy"></p><p>时段以运行 AnimeMachine 的设备时间为准，支持跨午夜。休眠期间暂停访问本地收藏库，保留已知状态；Ani-RSS 与其它媒体来源继续按各自的可用情况工作。</p><p>这项设置控制 AnimeMachine 对本地库的访问。其它应用仍可能使用同一块磁盘；磁盘是否实际休眠也取决于 NAS 和其它服务。</p><h2 id="查看历史记录与日志" tabindex="-1">查看历史记录与日志 <a class="header-anchor" href="#查看历史记录与日志" aria-label="Permalink to &quot;查看历史记录与日志&quot;">​</a></h2><p><strong>设置 → 历史记录</strong> 查看已执行的整理、目录及下载操作；<strong>设置 → 日志</strong> 查看运行提示。可先选择警告与错误，再按作品名称或关键字搜索。</p><p><img src="'+d+'" alt="历史记录：按操作与作品查找结果" loading="lazy"></p>',20)])])}const u=a(i,[["render",l]]);export{b as __pageData,u as default};
